package bowling

import "errors"

// Game keeps track of the rolls in a game of bowling.
type Game struct {
	rolls       []int
	frame       int // current frame, 0-indexed (0-9)
	rollInFrame int // which roll within the current frame (0, 1, or 2)
	firstRoll   int // pins knocked in the first roll of the current frame
	secondRoll  int // pins knocked in the second roll of the current frame
	gameOver    bool
}

// NewGame returns a new, empty bowling game.
func NewGame() *Game {
	return &Game{}
}

// Roll records a single ball throw that knocks down the given number of pins.
func (g *Game) Roll(pins int) error {
	if g.gameOver {
		return errors.New("Cannot roll after game is over")
	}
	if pins < 0 {
		return errors.New("Negative roll is invalid")
	}
	if pins > 10 {
		return errors.New("Pin count exceeds pins on the lane")
	}

	if g.frame < 9 {
		// Frames 1-9: a strike ends the frame; otherwise a second roll is needed.
		if g.rollInFrame == 0 {
			g.rolls = append(g.rolls, pins)
			if pins == 10 {
				g.advanceFrame()
			} else {
				g.firstRoll = pins
				g.rollInFrame = 1
			}
		} else {
			if g.firstRoll+pins > 10 {
				return errors.New("Pin count exceeds pins on the lane")
			}
			g.rolls = append(g.rolls, pins)
			g.advanceFrame()
		}
		return nil
	}

	// Tenth frame: bonus rolls are granted for strikes and spares.
	switch g.rollInFrame {
	case 0:
		g.rolls = append(g.rolls, pins)
		g.firstRoll = pins
		g.rollInFrame = 1
	case 1:
		if g.firstRoll == 10 {
			// First roll was a strike; this is a bonus roll.
			g.rolls = append(g.rolls, pins)
			g.secondRoll = pins
			g.rollInFrame = 2
		} else {
			if g.firstRoll+pins > 10 {
				return errors.New("Pin count exceeds pins on the lane")
			}
			g.rolls = append(g.rolls, pins)
			g.secondRoll = pins
			if g.firstRoll+pins == 10 {
				// Spare: one bonus roll.
				g.rollInFrame = 2
			} else {
				// Open frame: the game is over.
				g.gameOver = true
			}
		}
	default:
		// Third (bonus) roll.
		if g.firstRoll == 10 && g.secondRoll < 10 && g.secondRoll+pins > 10 {
			return errors.New("Pin count exceeds pins on the lane")
		}
		g.rolls = append(g.rolls, pins)
		g.gameOver = true
	}
	return nil
}

// advanceFrame moves to the next frame, resetting the per-frame roll state.
func (g *Game) advanceFrame() {
	g.frame++
	g.rollInFrame = 0
	g.firstRoll = 0
	g.secondRoll = 0
}

// Score returns the total score for a completed game.
func (g *Game) Score() (int, error) {
	if !g.gameOver {
		return 0, errors.New("Score cannot be taken until the end of the game")
	}

	score := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case g.rolls[i] == 10:
			// Strike: 10 plus the next two rolls.
			score += 10 + g.rolls[i+1] + g.rolls[i+2]
			i++
		case g.rolls[i]+g.rolls[i+1] == 10:
			// Spare: 10 plus the next roll.
			score += 10 + g.rolls[i+2]
			i += 2
		default:
			// Open frame: just the pins knocked down.
			score += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	return score, nil
}

